import java.util.Scanner;

public class Test {
  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    while (s.hasNextLine()) {
      s.nextLine();
      System.out.println(TextDocumentAnalysis.input(s.nextLine()));
    }
    s.close();
  }
  public static void main0(String[] args) {
    String[] ins = {
      "_Hello_Vasya(and_Petya)__bye_(and_OK)",
      "_a_(_b___c)__de_f(g_)__h__i(j_k_l)m__",
      "(LoooonG)__shOrt__(LoooonG)",
      "(___)",
      "Q(___)_u(_U)HG"
    };
    for (int i=0; i<ins.length; i++) {
      String s = TextDocumentAnalysis.input(ins[i]);
      System.out.println(s);
    }
  }
}

class TextDocumentAnalysis {
  public static String input(String str) {
    int len = str.length();
    boolean open = false;
    int wc = 0;
    int max = 0;
    int wlen = 0;
    for (int i=0; i<len; i++) {
      char ch = str.charAt(i);
      if (ch == '(') {
        if (wlen > 0) {
          if (wlen > max) max = wlen;
          wlen = 0;
        }
        open = true;
      } else if (ch == ')') {
        if (wlen > 0) {
          wc++;
          wlen = 0;
        }
        open = false;
      } else if (ch == '_') {
        if (wlen > 0) {
          if (open) {
            wc++;
          } else {
            if (wlen > max) max = wlen;
          }
          wlen = 0;
        }
      } else {
        wlen++;
      }
    }
    if (wlen > 0) {
      if (open) {
        wc++;
      } else {
        if (wlen > max) max = wlen;
      }
    }
    return max + " " + wc;
  }
}




